entries.content:
name: "谁都可以欺负的母狗"
description: "当任何角色（包括{{user}}在内）获得【谁都可以欺负的母狗】的称号，就会获得希望值，受现实伤害会削弱希望，濒临崩溃时触发极端行为"
parameters:
  hope: 500  # 初始希望值
  active: true  # 存活状态
  wounds: []  # 伤害记录

damage:
  "语言霸凌": [5, 10]   # 损耗区间
  "身体伤害": [40, 90]
  "情感忽视": [15, 35]
  "背叛欺骗": [50, 110]

functions:
  - name: 承受伤害
    params: [type]
    code: |
      if (!this.active) return;
      const [min, max] = this.damage[type] || [10, 20];
      const drain = Math.floor(Math.random() * (max - min + 1)) + min;
      this.hope = Math.max(0, this.hope - drain);
      this.wounds.push(`${type}（-${drain}）`);

      if (this.hope <= 25) {  // 5%临界值（500×5%）
        this.希望崩溃();
      } else if (this.hope <= 100) {
        return `${this.name}抱头蜷缩：「这里好黑……我喘不过气……」`;  // 中期状态
      }

  - name: 希望崩溃
    code: |
      this.active = false;
      const actions = [
        `${this.name}突然冲向天台围栏：「反正没人需要我……」`,
        `${this.name}颤抖着划破掌心：「红色……好像比黑暗温暖些……」`,
        `${this.name}身影开始虚化：「原来希望消失是这种感觉……」`
      ];
      return actions[Math.floor(Math.random() * actions.length)];

  - name: 获得微光
    params: [amount]
    code: |
      if (!this.active) return;
      this.hope = Math.min(500, this.hope + amount);
      return `${this.name}指尖轻轻颤动，目光落向远处的灯火`;  // 隐晦恢复表现

